class RandomFourierFeatures(nn.Module):
    scale: float
    n_features: int

    @nn.compact
    def __call__(self, x):
        B = (
            self.variable(
                "buffers",
                "B",
                nn.initializers.normal(),
                jax.random.PRNGKey(42),
                (
                    x.shape[-1],
                    self.n_features // 2,
                ),
            ).value
            * self.scale
        )
        x_proj = (2 * jnp.pi * x) @ B
        return jnp.concatenate([jnp.sin(x_proj), jnp.cos(x_proj)], axis=-1)
